    }
    if (onExpand) {
      onExpand(event, value);
    }
  };

  const onChange = e => {
    setValue(e.target.value);
    if (onChangeProp) {
      onChangeProp(e);
    }
  };

  return (
    <div
      tabIndex={expandedState ? '-1' : '0'}
      role="searchbox"
      ref={searchRef}
      onClick={event => handleExpand(event, true)}
      onFocus={event => handleExpand(event, true)}
      onBlur={event => !value && handleExpand(event, false)}
